import csv
def dump(f, n=80):
    print("==", f)
    try:
        with open(f) as fh:
            rows = list(csv.reader(fh))
    except Exception as e:
        print("ERR", e); return
    print("total rows:", len(rows))
    for row in rows[:n]:
        print(row)
    if len(rows) > n:
        print("... (truncated)")
for f in ["ae_ip_termination.csv", "ae_ip_termination_by_month.csv"]:
    dump(f)
dump("ae_ip.csv", 25)
